INSERT INTO public.reviews VALUES (1, 1, 'Alice Thompson', 5, 'Best dental experience ever! Dr. Smith is incredibly gentle and thorough. The whole team made me feel comfortable.', 'google', 'responded', 'Thank you so much, Alice! We love having you as a patient.', NULL, '2026-04-03 18:45:16.013258');
INSERT INTO public.reviews VALUES (2, 1, 'John Miller', 4, 'Good service and clean office. Wait time was a bit long but the care was excellent.', 'yelp', 'responded', 'Thanks for your feedback, John. We are working on reducing wait times.', NULL, '2026-04-03 18:45:16.013258');
INSERT INTO public.reviews VALUES (3, 3, 'David Kim', 5, 'Sarah Johnson is an exceptional attorney. Won my case and kept me informed throughout the entire process.', 'google', 'responded', 'Thank you David! It was a pleasure working with you.', NULL, '2026-04-03 18:45:16.013258');
INSERT INTO public.reviews VALUES (4, 5, 'Frank Lopez', 5, 'Called at 2am for an emergency pipe burst. They arrived in 30 minutes and fixed everything. Lifesavers!', 'google', 'responded', 'We are glad we could help, Frank! That is what we are here for.', NULL, '2026-04-03 18:45:16.013258');
INSERT INTO public.reviews VALUES (5, 5, 'Maria Santos', 3, 'Good work but pricing was higher than the initial estimate. Would appreciate more transparency.', 'yelp', 'pending', NULL, NULL, '2026-04-03 18:45:16.013258');
INSERT INTO public.reviews VALUES (6, 7, 'Hannah Moore', 5, 'Absolutely love my balayage! The stylists here are true artists. Best salon in San Antonio.', 'instagram', 'responded', 'You looked amazing Hannah! See you next month!', NULL, '2026-04-03 18:45:16.013258');
INSERT INTO public.reviews VALUES (7, 7, 'Jessica Lee', 5, 'The bridal package was perfect. My entire wedding party looked stunning. Highly recommend!', 'google', 'responded', 'Thank you Jessica! Your wedding was beautiful!', NULL, '2026-04-03 18:45:16.013258');
INSERT INTO public.reviews VALUES (8, 8, 'Sam Wilson', 4, 'Great massage experience. Very relaxing atmosphere. Only wish they had more availability on weekends.', 'google', 'pending', NULL, NULL, '2026-04-03 18:45:16.013258');
INSERT INTO public.reviews VALUES (9, 9, 'James Park', 5, 'Completely transformed my fitness level in 6 months. Coach knows exactly how to push you while keeping it safe.', 'google', 'responded', 'Your dedication is inspiring, James! Keep crushing it!', NULL, '2026-04-03 18:45:16.013258');
INSERT INTO public.reviews VALUES (10, 9, 'Amy Richards', 4, 'Solid training program. Wished they had more flexible scheduling for early morning sessions.', 'yelp', 'pending', NULL, NULL, '2026-04-03 18:45:16.013258');
INSERT INTO public.reviews VALUES (11, 10, 'Tina Foster', 5, 'Best CrossFit box I have ever been to. Community is incredible and coaching is top-notch.', 'google', 'responded', 'Welcome to the Thunder family, Tina!', NULL, '2026-04-03 18:45:16.013258');
INSERT INTO public.reviews VALUES (12, 11, 'Leo Martinez', 5, 'Dr. Patel is amazing with animals. My dogs actually get excited to go to the vet now!', 'google', 'responded', 'We adore your fur babies, Leo! See you all soon!', NULL, '2026-04-03 18:45:16.013258');
INSERT INTO public.reviews VALUES (13, 11, 'Susan Clark', 4, 'Very caring staff. Prices are fair for the quality of care. Easy online booking.', 'yelp', 'responded', 'Thank you for your kind words, Susan!', NULL, '2026-04-03 18:45:16.013258');
INSERT INTO public.reviews VALUES (14, 13, 'Nathan Brown', 5, 'Best Italian food outside of Italy! The homemade pasta is incredible. Catering was perfect for our event.', 'google', 'responded', 'Grazie mille, Nathan! We put love in every dish.', NULL, '2026-04-03 18:45:16.013258');
INSERT INTO public.reviews VALUES (15, 13, 'Laura Wright', 4, 'Wonderful food and atmosphere. Gets crowded on weekends so make a reservation.', 'yelp', 'pending', NULL, NULL, '2026-04-03 18:45:16.013258');
INSERT INTO public.reviews VALUES (16, 14, 'Mike Chen', 5, 'Best croissants in town! Coffee is excellent too. My go-to morning spot.', 'google', 'responded', 'Thank you Mike! See you tomorrow morning!', NULL, '2026-04-03 18:45:16.013258');
INSERT INTO public.reviews VALUES (17, 15, 'Victor Reyes', 5, 'Honest mechanics who do quality work. They saved me money by not recommending unnecessary repairs.', 'google', 'responded', 'Integrity is our priority, Victor! Thanks for trusting us.', NULL, '2026-04-03 18:45:16.013258');
INSERT INTO public.reviews VALUES (18, 15, 'Dan Cooper', 4, 'Good work on my transmission. Took a bit longer than estimated but they kept me updated.', 'yelp', 'pending', NULL, NULL, '2026-04-03 18:45:16.013258');
INSERT INTO public.reviews VALUES (19, 2, 'Peter Adams', 4, 'Friendly staff and nice office. Good with kids. Slightly pricey for basic procedures.', 'google', 'responded', 'Thanks Peter! We strive to make every visit comfortable.', NULL, '2026-04-03 18:45:16.013258');
