INSERT INTO public.case_studies VALUES (1, 'Gulf Ventures Southeast Asia Expansion', 'gulf-ventures-southeast-asia-expansion', 'Financial Services', 'Gulf Ventures, a prominent venture capital firm based in the GCC, had built a strong portfolio across the Middle East and North Africa. However, their leadership recognized that Southeast Asia represented a massive growth opportunity. The challenge was significant: they had no local presence, limited understanding of regulatory frameworks, and no established deal flow networks in the region.', 'We assembled a cross-functional advisory team with deep expertise in both Gulf capital markets and Southeast Asian startup ecosystems. Our engagement began with comprehensive market mapping across Indonesia, Vietnam, Thailand, and the Philippines, identifying sector-specific opportunities aligned with the firm''s investment thesis. We established local advisory partnerships and built a proprietary deal sourcing pipeline.', 'Gulf Ventures successfully entered three Southeast Asian markets within nine months. The firm deployed $25M across six portfolio companies, each sourced through our proprietary pipeline. Local co-investment partnerships were established with three leading regional venture funds.', 'This engagement fundamentally expanded Gulf Ventures'' geographic footprint and investment capability. Their Southeast Asian portfolio has already attracted follow-on interest from institutional LPs, and the firm''s AUM has grown by 30%.', '[{"value":"$25M","label":"Capital Deployed"},{"value":"9 Months","label":"Time to Market Entry"},{"value":"40+","label":"Countries in Deal Pipeline"},{"value":"6","label":"Portfolio Companies"}]', true, '2025-10-15 10:00:00');
INSERT INTO public.case_studies VALUES (2, 'AI Transformation at TechCorp Manufacturing', 'ai-transformation-techcorp-manufacturing', 'Manufacturing', 'TechCorp Manufacturing, a mid-market industrial manufacturer with $500M in annual revenue, was facing increasing competitive pressure from rivals who had invested heavily in automation. Their production lines relied on legacy systems with minimal data capture, and they had already wasted $2M on a failed AI proof-of-concept.', 'We started with a comprehensive AI readiness assessment evaluating data infrastructure, organizational capabilities, process maturity, and change readiness. We identified twelve high-impact use cases and prioritized predictive maintenance and demand forecasting. Our team managed vendor selection, solution architecture, data pipeline development, and integration with existing ERP systems.', 'The predictive maintenance solution was deployed across three facilities within six months, reducing unplanned downtime by 40%. The demand forecasting model improved accuracy by 35%, enabling a 20% reduction in inventory carrying costs. Combined, these delivered $15M in annual cost savings.', 'TechCorp''s AI transformation repositioned the company as an industry leader in smart manufacturing. The operational improvements directly contributed to a 300-basis-point margin expansion, and the board approved a $50M digital transformation budget.', '[{"value":"$15M","label":"Annual Cost Savings"},{"value":"40%","label":"Downtime Reduction"},{"value":"35%","label":"Forecast Accuracy Gain"},{"value":"6 Months","label":"Time to Production"}]', true, '2025-11-01 10:00:00');
INSERT INTO public.case_studies VALUES (3, 'Executive Leadership Build for HealthBridge', 'executive-leadership-build-healthbridge', 'Healthcare', 'HealthBridge, a digital health platform connecting patients with specialists through telemedicine, had grown rapidly from seed stage to Series B. However, the founder-led management team lacked the operational depth needed to scale. The board mandated a leadership upgrade as a condition of the next funding round.', 'We began with a detailed organizational assessment, working with the founders and board to define the target operating model for a Series C company. We then executed a retained search for five critical roles: CFO, CTO, VP of Commercial, VP of People, and VP of Operations, using our proprietary assessment process evaluating functional capability, cultural alignment, and founder collaboration readiness.', 'All five positions were filled within 60 days. The new CFO strengthened financial reporting critical during Series C due diligence. The CTO led a platform re-architecture improving uptime to 99.95%. HealthBridge successfully closed a $40M Series C round.', 'The leadership transformation demonstrated how the right executive team can unlock the next stage of growth. Revenue grew 150% year-over-year, and the company is on track for a Series D raise at a significantly higher valuation.', '[{"value":"5","label":"Executives Placed"},{"value":"60 Days","label":"Average Time to Fill"},{"value":"$40M","label":"Series C Raised"},{"value":"150%","label":"Revenue Growth YoY"}]', true, '2025-11-15 10:00:00');
INSERT INTO public.case_studies VALUES (4, 'Cross-Border Acquisition Advisory', 'cross-border-acquisition-advisory', 'Technology', 'A Middle Eastern technology group identified a European SaaS company as a strategic acquisition target. The target would provide critical product capabilities and European market access. However, the acquirer had limited cross-border M&A experience, and previous informal discussions had stalled due to misaligned expectations on valuation.', 'We were engaged as lead buy-side advisor, coordinating all workstreams across three jurisdictions. We conducted comprehensive due diligence across financial, legal, technical, and commercial dimensions. We designed a creative transaction structure including upfront payment, performance-based earnout, and talent retention packages.', 'The acquisition closed within four months at a price 15% below the seller''s initial asking price. 95% of the engineering team signed retention agreements. Regulatory approvals in all three jurisdictions were obtained without conditions.', 'Within 12 months of close, the combined entity launched three new products, European revenue grew by 80%, and the engineering team was fully integrated into global R&D.', '[{"value":"15%","label":"Below Asking Price"},{"value":"4 Months","label":"Time to Close"},{"value":"95%","label":"Talent Retention"},{"value":"3x","label":"Product Portfolio Growth"}]', true, '2025-12-01 10:00:00');
INSERT INTO public.case_studies VALUES (5, 'Digital Strategy for Education Platform', 'digital-strategy-education-platform', 'Education', 'A well-established education provider with 20 years of in-person delivery history was losing market share to digital-first competitors. Revenue had plateaued, instructor utilization was declining, and the board recognized an existential threat within five years without a comprehensive digital strategy.', 'We developed a three-year digital transformation roadmap. Phase one focused on platform architecture and content strategy. Phase two addressed pricing model redesign with subscription and micro-credential options. Phase three was a go-to-market plan targeting underserved regional markets in the Middle East, Africa, and Southeast Asia.', 'Student enrollment increased by 60% within 18 months. Digital revenue surpassed in-person revenue for the first time, reaching 55% of total revenue. The platform expanded to serve students in over 40 countries with localized content in four languages.', 'The organization attracted $20M in growth equity funding and is now exploring strategic partnerships with universities and corporate training programs.', '[{"value":"60%","label":"Enrollment Increase"},{"value":"40+","label":"Countries Reached"},{"value":"18 Months","label":"Time to Impact"},{"value":"$20M","label":"Growth Equity Raised"}]', true, '2025-12-15 10:00:00');
INSERT INTO public.case_studies VALUES (6, 'Real Estate Investment Fund Restructuring', 'real-estate-investment-fund-restructuring', 'Real Estate', 'A real estate investment fund managing approximately $200M in assets was significantly underperforming its target returns. Asset management practices were inconsistent, investor reporting was opaque, and key investors had begun requesting redemptions.', 'We designed and implemented a four-part restructuring plan: fund vehicle restructuring, institutional-grade reporting framework, portfolio-level strategic review with selective dispositions, and fund repositioning for new capital raises.', 'Fund returns improved from 4% IRR to 11% IRR within two years. Selective dispositions generated $45M in proceeds redeployed into higher-performing assets. A follow-on capital raise attracted $75M in new commitments.', 'Total assets under management grew from $200M to over $350M. The fund manager has since launched a second fund using the governance frameworks we designed.', '[{"value":"4% to 11%","label":"IRR Improvement"},{"value":"$75M","label":"New Capital Raised"},{"value":"$350M+","label":"Total AUM"},{"value":"2 Years","label":"Turnaround Timeline"}]', true, '2026-01-01 10:00:00');
INSERT INTO public.case_studies VALUES (7, 'Supply Chain Resilience for Global Retailer', 'supply-chain-resilience-global-retailer', 'Retail', 'A multi-national retailer with $2B in revenue experienced severe supply chain disruptions during the pandemic, resulting in $180M in lost sales. Their single-source dependency on Asian manufacturers left them vulnerable to port closures and logistics bottlenecks.', 'We conducted a comprehensive supply chain risk assessment and developed a multi-tier diversification strategy. This included identifying alternative suppliers across three continents, implementing real-time supply chain visibility tools, and restructuring procurement contracts with built-in contingency clauses.', 'Supply chain disruption risk was reduced by 65%. Lead times were shortened by 30% through nearshoring initiatives. Inventory carrying costs decreased by $25M annually while maintaining 99.2% product availability.', 'The retailer is now recognized as an industry leader in supply chain resilience. Their diversified supplier base and digital visibility tools have become a competitive advantage, attracting partnership interest from other retailers.', '[{"value":"65%","label":"Risk Reduction"},{"value":"30%","label":"Lead Time Improvement"},{"value":"$25M","label":"Annual Savings"},{"value":"99.2%","label":"Product Availability"}]', true, '2026-01-10 10:00:00');
INSERT INTO public.case_studies VALUES (8, 'Fintech Regulatory Expansion Across MENA', 'fintech-regulatory-expansion-mena', 'Financial Services', 'A European fintech company with a successful payments platform wanted to expand into the MENA region but faced complex and varying regulatory requirements across six target markets, each with different licensing frameworks, data localization rules, and consumer protection standards.', 'We mapped the regulatory landscape across all six target markets, developed a phased market entry sequence based on regulatory complexity and market opportunity, and managed the licensing application process in each jurisdiction. We also established relationships with local banking partners necessary for payment processing.', 'Licenses were secured in four markets within 12 months, ahead of the original 18-month timeline. The first market (UAE) was operational within 6 months and achieved $50M in transaction volume within the first quarter. Banking partnerships were established in all target markets.', 'The fintech company is now the first European payments platform licensed across four MENA markets simultaneously, giving them a significant first-mover advantage in the region.', '[{"value":"4","label":"Markets Licensed"},{"value":"6 Months","label":"Time to First Market"},{"value":"$50M","label":"Q1 Transaction Volume"},{"value":"33%","label":"Ahead of Schedule"}]', true, '2026-01-20 10:00:00');
INSERT INTO public.case_studies VALUES (9, 'Enterprise SaaS Go-to-Market Transformation', 'enterprise-saas-go-to-market-transformation', 'Technology', 'A B2B SaaS company with a strong product had plateaued at $30M ARR. Their founder-led sales motion was not scaling, win rates were declining, and the average sales cycle had grown from 45 to 90 days. The board needed a path to $100M ARR within three years.', 'We redesigned the entire go-to-market engine: segmented the customer base into distinct buyer personas, rebuilt the sales process with clear stage gates and qualification criteria, implemented a product-led growth motion for the SMB segment, and hired three enterprise account executives through our executive search practice.', 'ARR grew from $30M to $52M within 18 months. Win rates improved from 18% to 32%. Average sales cycle was reduced back to 50 days. Net revenue retention improved from 95% to 118%, indicating strong expansion within existing accounts.', 'The company successfully raised a $75M Series C at a $500M valuation, citing the transformed go-to-market engine as a key factor in investor confidence.', '[{"value":"73%","label":"ARR Growth"},{"value":"32%","label":"Win Rate"},{"value":"50 Days","label":"Sales Cycle"},{"value":"$75M","label":"Series C Raised"}]', true, '2026-01-30 10:00:00');
INSERT INTO public.case_studies VALUES (10, 'Healthcare System Digital Patient Experience', 'healthcare-system-digital-patient-experience', 'Healthcare', 'A regional healthcare system with 12 hospitals and 50+ clinics was losing patients to digitally-savvy competitors offering seamless online scheduling, telemedicine, and patient portals. Patient satisfaction scores had dropped to the 35th percentile, and patient acquisition costs had doubled over three years.', 'We designed a comprehensive digital patient experience strategy spanning the entire care journey — from discovery and scheduling through treatment and follow-up. This included vendor selection for a unified patient portal, telemedicine platform integration, automated appointment reminders, and a patient feedback loop tied to operational improvements.', 'Patient satisfaction scores improved from the 35th to the 78th percentile within 12 months. Online scheduling adoption reached 65% of all appointments. Telemedicine visits grew to represent 22% of outpatient encounters. Patient acquisition cost decreased by 40%.', 'The healthcare system became a regional reference site for digital patient experience, attracting partnership inquiries from other health systems looking to replicate their approach.', '[{"value":"35th to 78th","label":"Satisfaction Percentile"},{"value":"65%","label":"Online Scheduling"},{"value":"22%","label":"Telehealth Adoption"},{"value":"40%","label":"Cost Reduction"}]', true, '2026-02-05 10:00:00');
INSERT INTO public.case_studies VALUES (11, 'Private Equity Portfolio Optimization', 'private-equity-portfolio-optimization', 'Financial Services', 'A mid-market private equity firm with $1.2B AUM was experiencing declining returns across its portfolio of 14 companies. Three portfolio companies were underperforming their business plans, management teams were not executing consistently, and the fund was approaching its investment period end.', 'We conducted a portfolio-wide operational assessment, identifying specific value creation levers for each company. For the three underperforming companies, we developed turnaround plans including leadership changes, cost optimization, and revenue acceleration initiatives. We also placed interim operating executives through our talent practice.', 'Portfolio EBITDA grew by 28% aggregate within 18 months. Two of the three underperforming companies returned to plan. The fund successfully executed two exits at combined valuations 40% above original underwriting assumptions.', 'The PE firm adopted our portfolio assessment methodology as a standard practice for all future investments, embedding it into their 100-day post-acquisition playbook.', '[{"value":"28%","label":"Portfolio EBITDA Growth"},{"value":"2","label":"Successful Exits"},{"value":"40%","label":"Above Underwriting"},{"value":"18 Months","label":"Turnaround Time"}]', true, '2026-02-10 10:00:00');
INSERT INTO public.case_studies VALUES (12, 'Renewable Energy Market Entry Strategy', 'renewable-energy-market-entry-strategy', 'Energy', 'A European renewable energy developer wanted to enter the Middle East market to capitalize on the region''s massive solar investment plans. They had no local presence, limited understanding of government procurement processes, and faced competition from established Chinese and Korean developers with significant cost advantages.', 'We developed a differentiated market entry strategy focused on partnerships with local developers and government entities. We identified and facilitated introductions to three sovereign wealth fund-backed development platforms, structured joint venture frameworks, and navigated the regulatory approval process for foreign energy developers.', 'The developer secured its first 500MW solar project through a JV with a local partner within 14 months. The project pipeline grew to 2GW of identified opportunities across three Gulf states. Two additional JV partnerships were established.', 'The developer is now recognized as one of the leading European solar platforms in the Middle East, with a pipeline value exceeding $1.5B.', '[{"value":"500MW","label":"First Project"},{"value":"2GW","label":"Pipeline"},{"value":"14 Months","label":"Time to First Deal"},{"value":"$1.5B+","label":"Pipeline Value"}]', true, '2026-02-15 10:00:00');
INSERT INTO public.case_studies VALUES (13, 'Luxury Hospitality Brand International Expansion', 'luxury-hospitality-brand-expansion', 'Hospitality', 'A boutique luxury hospitality brand with five properties in Europe wanted to expand into the Middle East and Southeast Asia. The brand had a strong identity but no international operating infrastructure, no local partnerships, and faced the challenge of maintaining brand standards across culturally diverse markets.', 'We developed a franchise and management agreement strategy tailored to each target market. We identified and vetted potential local partners and real estate developers, structured commercial terms, and created a brand standards compliance framework for international operations. We also recruited regional managing directors through our executive search practice.', 'Three management agreements were signed within 12 months covering Dubai, Singapore, and Bali. The first property (Dubai) opened 20 months after engagement, achieving 85% occupancy in its first quarter — 15 points above pro forma. Two additional properties are under development.', 'The brand successfully transitioned from a European operator to a global luxury hospitality platform. Revenue from international operations is projected to exceed European revenues within three years.', '[{"value":"3","label":"New Properties Signed"},{"value":"85%","label":"First Quarter Occupancy"},{"value":"20 Months","label":"Time to Open"},{"value":"5 to 8","label":"Portfolio Growth"}]', true, '2026-02-20 10:00:00');
INSERT INTO public.case_studies VALUES (14, 'Agricultural Technology Platform Scale-Up', 'agtech-platform-scale-up', 'Agriculture', 'An agricultural technology startup with a promising crop monitoring platform had strong pilot results but was struggling to scale beyond 50 farm customers. The sales process was long, farmer adoption rates were low, and the company was running out of runway with only 8 months of cash remaining.', 'We restructured the business model from direct sales to a channel partnership strategy through agricultural cooperatives and input suppliers. We redesigned the pricing model to reduce upfront costs with usage-based pricing. We also led a bridge financing round to extend runway and placed a commercial VP through our talent practice.', 'Customer base grew from 50 to 400 farms within 12 months. Revenue grew 5x from $600K to $3M ARR. The company secured a $12M Series A round at a $50M valuation. Three strategic channel partnerships were established with major agricultural cooperatives.', 'The platform is now positioned as the leading crop intelligence solution in its target market, with expansion plans into three additional countries. The channel partnership model has become a replicable growth engine.', '[{"value":"8x","label":"Customer Growth"},{"value":"5x","label":"Revenue Growth"},{"value":"$12M","label":"Series A Raised"},{"value":"12 Months","label":"Transformation Time"}]', true, '2026-02-25 10:00:00');
INSERT INTO public.case_studies VALUES (15, 'Government Digital Transformation Program', 'government-digital-transformation-program', 'Government', 'A Gulf state government ministry responsible for business licensing and permits was processing applications with paper-based workflows that took an average of 45 days. This was creating friction for foreign investors and undermining the country''s economic diversification goals.', 'We designed and managed the implementation of a fully digital licensing platform covering 200+ permit types. The program included process re-engineering to eliminate redundant approvals, integration with other government systems, a multilingual user interface, and a change management program for 500+ ministry staff.', 'Average processing time was reduced from 45 days to 4 days for standard permits. Online application adoption reached 92% within six months of launch. Foreign investor applications increased by 35%. The platform processed over 50,000 applications in its first year.', 'The ministry won a regional government innovation award for the platform. The solution has since been adopted as a template by two other ministries in the same government.', '[{"value":"45 to 4 Days","label":"Processing Time"},{"value":"92%","label":"Digital Adoption"},{"value":"35%","label":"More Foreign Investment"},{"value":"50K+","label":"Applications Year 1"}]', true, '2026-03-01 10:00:00');
INSERT INTO public.case_studies VALUES (16, 'Cybersecurity Practice Build for Consulting Firm', 'cybersecurity-practice-build', 'Technology', 'A mid-size management consulting firm recognized the need to build a cybersecurity advisory practice to serve their existing client base. However, they had no cybersecurity expertise internally, the talent market was extremely competitive, and they needed to move quickly before competitors captured the opportunity.', 'We designed the practice from scratch: defined service offerings, built the commercial model, created marketing collateral and thought leadership, and recruited a practice leader plus four senior consultants through our executive search practice. We also facilitated three technology partnerships with cybersecurity vendors.', 'The cybersecurity practice achieved $4M in revenue in its first year. Five new clients were acquired from the firm''s existing relationship base. The practice leader became a recognized industry voice, generating significant inbound interest. Utilization rates reached 72% — above the firm''s target.', 'The consulting firm successfully diversified its revenue streams and deepened client relationships through the new practice. The approach has become a playbook for launching additional practices.', '[{"value":"$4M","label":"First Year Revenue"},{"value":"5","label":"New Clients"},{"value":"72%","label":"Utilization Rate"},{"value":"12 Months","label":"Practice Launch"}]', true, '2026-03-05 10:00:00');
INSERT INTO public.industries VALUES (1, 'Healthcare', 'healthcare', 'MCG helps healthcare organizations navigate digital transformation, regulatory complexity, and talent challenges to deliver better outcomes and sustainable growth.', 'Accelerating digital transformation while maintaining care quality and compliance. Navigating evolving regulatory requirements across multiple jurisdictions. Attracting and retaining top clinical and executive talent. Protecting patient data and ensuring robust cybersecurity posture. Expanding into new geographies with different healthcare systems.', 'Our healthcare practice combines deep domain expertise with our integrated advisory model. We work alongside leadership teams to build strategies that balance innovation with compliance, helping organizations adopt new technologies, enter new markets, and secure the talent they need — all while keeping patient outcomes at the center.', 'Digital health strategy and technology roadmap development. Regulatory and compliance navigation for multi-market operations. Executive search for clinical, operational, and C-suite leadership. Patient data security assessment and cybersecurity advisory. Cross-border market entry and international expansion planning.', '[{"title":"AI Transformation","slug":"ai-transformation"},{"title":"Global Expansion","slug":"global-expansion"},{"title":"Talent & Executive Search","slug":"talent-executive-search"}]', true, '2025-09-01 10:00:00');
INSERT INTO public.industries VALUES (2, 'Technology', 'technology', 'MCG partners with technology companies — from high-growth startups to mature platforms — to scale operations, acquire top talent, and stay ahead in rapidly evolving markets.', 'Scaling operations and infrastructure to match rapid revenue growth. Acquiring and retaining world-class engineering and leadership talent. Expanding into new markets with different competitive dynamics. Adopting and integrating AI capabilities into existing products. Maintaining competitive advantage against well-funded incumbents and agile newcomers.', 'Technology moves fast, and so do we. Our technology practice is built around speed, precision, and practical execution. We help companies identify and capture growth opportunities, build the leadership teams needed to execute at scale, and navigate the complexity of global expansion.', 'Growth strategy and market opportunity sizing for scaling companies. Executive search and organizational design for high-growth teams. International market entry and go-to-market strategy. AI readiness assessment and implementation roadmap. Capital raising strategy and investor targeting.', '[{"title":"Strategy & Growth","slug":"strategy-growth"},{"title":"Talent & Executive Search","slug":"talent-executive-search"},{"title":"AI Transformation","slug":"ai-transformation"}]', true, '2025-09-01 10:00:00');
INSERT INTO public.industries VALUES (3, 'Financial Services', 'financial-services', 'MCG advises banks, insurers, asset managers, and fintech companies on navigating disruption, regulatory complexity, and cross-border deal structuring.', 'Responding to fintech disruption and evolving customer expectations. Managing regulatory complexity across multiple jurisdictions. Structuring and executing cross-border deals and partnerships. Driving digital transformation without disrupting core operations. Retaining senior talent in a highly competitive hiring environment.', 'Financial services is being reshaped by technology, regulation, and shifting customer behavior. Our practice brings together strategy, deal, and talent expertise to help financial institutions and fintech companies navigate this complexity.', 'Fintech partnership and competitive response strategy. Multi-jurisdiction regulatory compliance and licensing advisory. Cross-border M&A advisory and deal structuring. Digital transformation roadmap and vendor selection. Executive search for risk, compliance, and technology leadership.', '[{"title":"Investment Advisory","slug":"investment-advisory"},{"title":"Global Expansion","slug":"global-expansion"},{"title":"Strategy & Growth","slug":"strategy-growth"}]', true, '2025-09-01 10:00:00');
INSERT INTO public.industries VALUES (4, 'Education', 'education', 'MCG supports education institutions and EdTech companies in adopting technology, securing funding, and expanding their reach to learners worldwide.', 'Adopting EdTech solutions that genuinely improve learning outcomes. Securing sustainable funding and diversifying revenue streams. Expanding programs into international markets. Developing compelling digital content and online learning experiences. Driving student engagement and retention in a competitive landscape.', 'Education is undergoing a fundamental transformation driven by technology, globalization, and changing learner expectations. Our education practice helps institutions and EdTech companies seize this opportunity with outcomes-focused advisory.', 'EdTech evaluation, selection, and implementation advisory. Funding strategy and investor readiness for education ventures. International market entry and partnership development. Digital content strategy and online program design. Executive search for academic, operational, and technology leadership.', '[{"title":"AI Transformation","slug":"ai-transformation"},{"title":"Strategy & Growth","slug":"strategy-growth"},{"title":"Investment Advisory","slug":"investment-advisory"}]', true, '2025-09-01 10:00:00');
INSERT INTO public.industries VALUES (5, 'Real Estate', 'real-estate', 'MCG advises real estate developers, investors, and operators on navigating market cycles, structuring deals, and leveraging PropTech for competitive advantage.', 'Navigating market cycles and timing investment decisions in volatile conditions. Structuring cross-border real estate investment and development deals. Evaluating and adopting PropTech solutions to improve operations. Meeting sustainability and ESG expectations from investors. Optimizing deal structuring for tax efficiency and risk management.', 'Real estate is a capital-intensive, cycle-sensitive industry that rewards those who combine local knowledge with global perspective. Our practice brings together investment advisory, market entry, and operational expertise.', 'Market cycle analysis and investment timing advisory. Cross-border real estate investment structuring and execution. PropTech evaluation and digital transformation for property operations. Sustainability and ESG strategy for real estate portfolios. Deal structuring, due diligence, and transaction support.', '[{"title":"Investment Advisory","slug":"investment-advisory"},{"title":"Global Expansion","slug":"global-expansion"},{"title":"AI Transformation","slug":"ai-transformation"}]', true, '2025-09-01 10:00:00');
INSERT INTO public.industries VALUES (6, 'International Trade', 'international-trade', 'MCG helps businesses navigate the complexities of global trade — from supply chain optimization and regulatory compliance to market access and partner network development.', 'Building resilient supply chains that withstand disruption and geopolitical risk. Navigating trade regulations, tariffs, and compliance requirements across markets. Gaining access to new markets and establishing credible local presence. Managing currency risk and foreign exchange exposure. Identifying and vetting reliable partners and distributors.', 'International trade is the backbone of global growth, but it comes with complexity that can stall even the most ambitious expansion plans. Our practice combines regulatory expertise, supply chain knowledge, and global corridor networks.', 'Supply chain resilience assessment and optimization strategy. Trade compliance and regulatory navigation across target markets. Market access strategy and local partner identification. Currency risk management and hedging strategy advisory. Global partner network development and due diligence.', '[{"title":"Global Expansion","slug":"global-expansion"},{"title":"Strategy & Growth","slug":"strategy-growth"},{"title":"Investment Advisory","slug":"investment-advisory"}]', true, '2025-09-01 10:00:00');
INSERT INTO public.industries VALUES (7, 'Manufacturing', 'manufacturing', 'MCG helps manufacturers embrace Industry 4.0, optimize operations, and build resilient supply chains in an increasingly automated and globalized landscape.', 'Adopting automation and AI to remain competitive against low-cost producers. Transitioning from legacy systems to smart manufacturing platforms. Building supply chain resilience across geopolitical boundaries. Attracting technical and leadership talent in a tight labor market. Meeting sustainability targets while maintaining profitability.', 'Our manufacturing practice focuses on the intersection of operational excellence and digital transformation. We help manufacturers identify and implement the right technologies, restructure operations for efficiency, and build the leadership capabilities needed to compete globally.', 'Industry 4.0 readiness assessment and implementation roadmap. Predictive maintenance and quality control AI deployment. Supply chain diversification and nearshoring strategy. Executive search for operations, technology, and plant leadership. ESG and sustainability strategy for manufacturing operations.', '[{"title":"AI Transformation","slug":"ai-transformation"},{"title":"Strategy & Growth","slug":"strategy-growth"},{"title":"Talent & Executive Search","slug":"talent-executive-search"}]', true, '2025-09-01 10:00:00');
INSERT INTO public.industries VALUES (8, 'Energy', 'energy', 'MCG advises energy companies — from traditional oil and gas to renewable developers — on navigating the energy transition, market entry, and capital strategy.', 'Navigating the energy transition and shifting investment landscape. Entering new markets with complex regulatory and permitting frameworks. Securing project finance and attracting ESG-aligned capital. Managing operational risk across distributed generation assets. Building diverse leadership teams for evolving energy businesses.', 'The energy sector is undergoing its most significant transformation in a century. Our practice helps companies position themselves at the intersection of traditional energy expertise and clean energy innovation.', 'Energy transition strategy and portfolio optimization. Market entry and regulatory navigation for renewable developers. Project finance advisory and ESG investor targeting. Operational risk management for distributed assets. Executive search for energy transition leadership.', '[{"title":"Investment Advisory","slug":"investment-advisory"},{"title":"Global Expansion","slug":"global-expansion"},{"title":"Strategy & Growth","slug":"strategy-growth"}]', true, '2025-09-01 10:00:00');
INSERT INTO public.industries VALUES (9, 'Retail & Consumer', 'retail-consumer', 'MCG helps retail and consumer brands adapt to changing consumer behaviors, build omnichannel strategies, and expand into high-growth international markets.', 'Adapting to rapidly shifting consumer preferences and digital-first shopping behaviors. Building cohesive omnichannel experiences across physical and digital. Expanding internationally while maintaining brand consistency. Optimizing supply chains for speed, cost, and sustainability. Leveraging data and AI for personalization and demand forecasting.', 'Retail is being transformed by technology, sustainability expectations, and changing consumer behaviors. Our practice helps brands and retailers build strategies that blend digital innovation with operational excellence.', 'Omnichannel strategy and digital commerce optimization. International brand expansion and market entry planning. Supply chain optimization and sustainability advisory. AI-powered demand forecasting and personalization strategy. Executive search for retail, digital, and supply chain leadership.', '[{"title":"AI Transformation","slug":"ai-transformation"},{"title":"Global Expansion","slug":"global-expansion"},{"title":"Strategy & Growth","slug":"strategy-growth"}]', true, '2025-09-01 10:00:00');
INSERT INTO public.industries VALUES (10, 'Government & Public Sector', 'government-public-sector', 'MCG advises government entities and public sector organizations on digital transformation, economic development, and institutional modernization.', 'Modernizing legacy systems and processes while maintaining service continuity. Attracting and retaining technical talent against private sector competition. Implementing citizen-facing digital services at scale. Managing multi-stakeholder procurement and vendor relationships. Driving economic diversification and investment attraction programs.', 'Governments worldwide are under pressure to modernize, digitize, and deliver better outcomes for citizens. Our public sector practice combines strategic advisory with practical implementation experience across multiple jurisdictions.', 'Digital government strategy and citizen service transformation. Economic development and investment attraction advisory. Public sector procurement optimization and vendor management. E-government platform design and implementation oversight. Public sector leadership search and organizational design.', '[{"title":"AI Transformation","slug":"ai-transformation"},{"title":"Strategy & Growth","slug":"strategy-growth"},{"title":"Talent & Executive Search","slug":"talent-executive-search"}]', true, '2025-09-01 10:00:00');
INSERT INTO public.industries VALUES (11, 'Hospitality & Tourism', 'hospitality-tourism', 'MCG advises hospitality brands, hotel groups, and tourism authorities on expansion strategy, brand development, and operational excellence across global markets.', 'Expanding hotel and resort brands into new international markets. Maintaining brand standards and guest experience across diverse cultures. Adapting to changing traveler expectations and digital-first booking behaviors. Attracting and retaining hospitality leadership in competitive markets. Developing sustainable tourism strategies that balance growth with conservation.', 'The hospitality industry thrives on experience, and great experiences require strategic planning and operational precision. Our practice helps hospitality companies expand globally while maintaining the guest experience standards that define their brand.', 'International brand expansion and franchise strategy. Hotel operations optimization and revenue management advisory. Hospitality technology evaluation and digital guest experience. Sustainable tourism strategy and ESG compliance. Executive search for hospitality and tourism leadership.', '[{"title":"Global Expansion","slug":"global-expansion"},{"title":"Strategy & Growth","slug":"strategy-growth"},{"title":"Talent & Executive Search","slug":"talent-executive-search"}]', true, '2025-09-01 10:00:00');
INSERT INTO public.industries VALUES (12, 'Media & Entertainment', 'media-entertainment', 'MCG advises media companies, content creators, and entertainment platforms on digital distribution, monetization strategy, and global content expansion.', 'Navigating the shift from traditional to digital distribution models. Monetizing content across fragmented global platforms and markets. Protecting intellectual property across jurisdictions. Building data-driven audience engagement and retention strategies. Attracting creative and technical talent in a hyper-competitive market.', 'Media and entertainment is being reshaped by streaming, social platforms, and AI-generated content. Our practice helps content creators and media companies build sustainable business models in this rapidly evolving landscape.', 'Digital distribution strategy and platform partnership advisory. Content monetization and licensing strategy across markets. Audience analytics and data-driven programming advisory. IP protection and rights management across jurisdictions. Executive search for creative, technology, and commercial leadership.', '[{"title":"AI Transformation","slug":"ai-transformation"},{"title":"Strategy & Growth","slug":"strategy-growth"},{"title":"Investment Advisory","slug":"investment-advisory"}]', true, '2025-09-01 10:00:00');
INSERT INTO public.industries VALUES (13, 'Logistics & Transportation', 'logistics-transportation', 'MCG advises logistics operators, shipping lines, and transportation companies on digital transformation, route optimization, and cross-border operations.', 'Digitizing operations across complex, multi-modal logistics networks. Optimizing routes and capacity utilization with AI and real-time data. Navigating regulatory requirements across borders and transport modes. Building resilience against supply chain disruptions and geopolitical risks. Attracting technology talent to traditionally non-tech industries.', 'Logistics is the invisible engine of global commerce, and it is being transformed by technology, sustainability requirements, and shifting trade patterns. Our practice helps logistics companies modernize operations and capture new growth opportunities.', 'Logistics digitization and real-time visibility platform strategy. Route optimization and capacity planning using AI. Cross-border regulatory compliance and trade facilitation. Fleet electrification and sustainability roadmap. Executive search for logistics, technology, and operations leadership.', '[{"title":"AI Transformation","slug":"ai-transformation"},{"title":"Global Expansion","slug":"global-expansion"},{"title":"Strategy & Growth","slug":"strategy-growth"}]', true, '2025-09-01 10:00:00');
INSERT INTO public.industries VALUES (14, 'Professional Services', 'professional-services', 'MCG advises law firms, accounting practices, and consulting firms on growth strategy, practice development, and digital transformation.', 'Differentiating in an increasingly commoditized professional services market. Adopting technology to improve efficiency without compromising quality. Expanding into new practice areas and geographic markets. Attracting and retaining top professional talent. Building scalable business development and client relationship processes.', 'Professional services firms face unique growth challenges: their product is their people, and scaling requires careful balance between growth and quality. Our practice helps professional services firms grow strategically while maintaining the standards their clients expect.', 'Growth strategy and market positioning for professional services. Practice area development and new market entry. Legal tech and professional services technology advisory. Business development process design and CRM optimization. Executive search and lateral partner recruitment.', '[{"title":"Strategy & Growth","slug":"strategy-growth"},{"title":"AI Transformation","slug":"ai-transformation"},{"title":"Talent & Executive Search","slug":"talent-executive-search"}]', true, '2025-09-01 10:00:00');
INSERT INTO public.industries VALUES (15, 'Telecommunications', 'telecommunications', 'MCG advises telecom operators, infrastructure companies, and digital service providers on network strategy, digital transformation, and market expansion.', 'Investing in 5G and fiber infrastructure while managing legacy network costs. Transitioning from connectivity provider to digital services platform. Competing with OTT players for consumer attention and revenue. Managing regulatory complexity across markets and spectrum licensing. Building digital-first customer experiences that reduce churn.', 'Telecommunications is at the center of the digital economy, but operators face intense pressure from all sides. Our practice helps telecom companies evolve their business models, invest in the right infrastructure, and build digital capabilities that drive future growth.', 'Network investment strategy and 5G deployment planning. Digital services platform strategy and monetization. Customer experience transformation and churn reduction. Regulatory and spectrum licensing advisory across markets. Executive search for telecom, technology, and digital leadership.', '[{"title":"AI Transformation","slug":"ai-transformation"},{"title":"Strategy & Growth","slug":"strategy-growth"},{"title":"Investment Advisory","slug":"investment-advisory"}]', true, '2025-09-01 10:00:00');
INSERT INTO public.industries VALUES (16, 'Nonprofit & Social Impact', 'nonprofit-social-impact', 'MCG advises nonprofit organizations, foundations, and impact investors on strategy, organizational effectiveness, and sustainable funding models.', 'Securing sustainable funding beyond traditional grant cycles. Measuring and communicating impact to donors and stakeholders. Scaling programs while maintaining mission alignment and quality. Attracting leadership talent at competitive nonprofit compensation levels. Adapting to digital-first engagement and fundraising expectations.', 'Nonprofits face many of the same strategic challenges as for-profit organizations but with additional constraints around funding, governance, and mission alignment. Our practice helps mission-driven organizations achieve greater impact through better strategy and execution.', 'Strategic planning and theory of change development. Sustainable funding model design and donor diversification. Impact measurement framework and reporting. Organizational design and nonprofit leadership search. Digital transformation and constituent engagement strategy.', '[{"title":"Strategy & Growth","slug":"strategy-growth"},{"title":"Talent & Executive Search","slug":"talent-executive-search"},{"title":"AI Transformation","slug":"ai-transformation"}]', true, '2025-09-01 10:00:00');
